fn encode_shift(s: Vec<char>) -> Vec<char> {
    // For each character c in the input vector, compute
    // ((c as u8 - b'a' + 5) % 26 + b'a') as the new character.
    s.into_iter()
        .map(|c| {
            let base = b'a';
            let shifted = (c as u8 - base + 5) % 26 + base;
            shifted as char
        })
        .collect()
}

